      rejected = true;
    }
    if (!rejected) throw new Error(`document-open independent exchange codec admitted ${mutation.name}`);
  }
  for (const consumeCase of fixture.socketConsumeCases) {
    let candidate = structuredClone(fixture.validPlan);
