  const trusted = readFileSync(join(repoRoot, "🌎️hub", "🗿️artifact-authority", "🔏️trusted-catalog", "🦀️.rs"), "utf8");
  const startup = readFileSync(join(repoRoot, "🌎️hub", "🏗️bootstrap", "🦀️.rs"), "utf8");
