    "VerifiedGisMapArtifactBindingV1",
    "Arc<VerifiedTrustedCatalog>",
    "selected_document_open",
    "gis_map_inference_service",
    "executable_identity",
    "component_blake3",
    "descriptor_byte_sha256",
    "execution_protocol",
    "parent_dialect",
    "DocumentOpenSurfaceRoleV1::Editor",
    "grant.read",
    "grant.write",
    "grant.observe",
    "semio.hub.gis-map-frozen-binding/v1\\0",
