  const assert: (typeof import("node:assert"))["strict"] = (await import("node:assert/strict")).default;
  const validateBundle = hubSchemaExport(repoRoot, "schema://hub.artifact-authority.trusted-catalog/TrustedBundleV1");
  assert.deepEqual(Object.keys(fixture), ["schema", "source", "packageReferenceHash", "descriptorOwnerHash", "cases"]);
  assert.equal(fixture.schema, "semio.hub.trusted-catalog-identity-roles/v1");
  assert.equal(fixture.source, "../👥️two-package/🔣️.json");
  assert.equal(fixture.packageReferenceHash, "componentBlake3");
  assert.equal(fixture.descriptorOwnerHash, "componentSha256");
  assert.deepEqual(fixture.cases.map((row: any) => row.change), ["none", "blake3-owner", "descriptor-owner", "zero-owner", "bare-kind", "bare-surface"]);
  for (const row of fixture.cases) assert.deepEqual(Object.keys(row), ["change", "codec", "open"]);
  const source = JSON.parse(readFileSync(join(root, fixture.source), "utf8"));
  assert(validateBundle(source.bundle), "identity-role source bundle must satisfy the scope-owned contract");
  const bytes = Buffer.from(source.componentHex, "hex");
  const sha256 = createHash("sha256").update(bytes).digest("hex");
  if (sha256 !== source.componentSha256 || source.componentSha256 === source.componentBlake3) throw new Error("catalog hash roles lost their independent byte identities");
  const selected = source.bundle.packages[0],
    target = selected.openTargets[0];
  if (!target.artifactKind.startsWith("s.") || target.surfaceId !== `${target.artifactKind}@1/*#editor` || target.appId !== target.surfaceId) throw new Error("catalog fixture kind/surface is not exact canonical identity");
  for (const test of fixture.cases) {
    let ownerHash = source.componentSha256,
      kind = target.artifactKind,
      surface = target.surfaceId;
    switch (test.change) {
      case "blake3-owner":
        ownerHash = source.componentBlake3;
        break;
      case "descriptor-owner":
        ownerHash = selected.descriptor.sha256;
        break;
      case "zero-owner":
        ownerHash = "00".repeat(32);
        break;
      case "bare-kind":
        kind = kind.slice(2);
        break;
      case "bare-surface":
        surface = surface.slice(2);
        break;
    }
    const codec = ownerHash === sha256 && kind === selected.nativeCodecs[0].artifactKind;
    const open = codec && surface === target.appId;
    if (codec !== test.codec || open !== test.open) throw new Error(`catalog identity role mismatch ${test.change}`);
  }
  console.log(`trusted-catalog-identity-oracle: exact=${fixture.cases.length} canonical-kind=1 descriptor-sha256=1 package-ref-blake3=distinct; no GIS provider activation`);
}

type TrustedBootstrapCodec = { readonly artifactKind: string; readonly artifactSchema: string; readonly packSchemaHash: string };
type TrustedBootstrapIdentityV1 = Readonly<{ pluginId: string; packageId: string; version: string }>;
type TrustedBootstrapDescriptorClaimsV1 = Readonly<{
  identity: TrustedBootstrapIdentityV1;
  executionProtocol: Readonly<DocumentExecutionProtocolV1>;
  directDependencies: readonly Readonly<{ pluginId: string; version: string }>[];
}>;

/** 🔢️ Requires canonical unsigned 64-bit version spelling for the strict local profile. */
function trustedBootstrapVersion(value: unknown): string {
  if (typeof value !== "string" || value.length > 62 || !/^(?:0|[1-9][0-9]*)\.(?:0|[1-9][0-9]*)\.(?:0|[1-9][0-9]*)$/u.test(value) || value.split(".").some((part) => BigInt(part) > 18_446_744_073_709_551_615n)) throw new Error("trusted dependency version is not canonical u64");
  return value;
}

/** 🪪️ Copies one closed bounded concrete package identity. */
function trustedBootstrapIdentity(value: unknown): TrustedBootstrapIdentityV1 {
  const row = documentOpenNeutralObject(value, ["pluginId", "packageId", "version"]);
  for (const key of ["pluginId", "packageId"] as const) if (typeof row[key] !== "string" || Buffer.byteLength(row[key], "utf8") > 256 || row[key].length === 0 || row[key].trim() !== row[key] || Buffer.from(row[key], "utf8").toString("utf8") !== row[key] || /\p{Cc}/u.test(row[key])) throw new Error("trusted dependency identity is not bounded");
  return Object.freeze({ pluginId: row.pluginId as string, packageId: row.packageId as string, version: trustedBootstrapVersion(row.version) });
}

/** 🔠️ Mirrors Rust string tuple ordering, including non-BMP UTF-8 identities. */
function trustedBootstrapTupleOrder(left: readonly string[], right: readonly string[]): number {
  for (let index = 0; index < left.length; index++) {
    const order = Buffer.compare(Buffer.from(left[index], "utf8"), Buffer.from(right[index], "utf8"));
    if (order) return order;
  }
  return 0;
}

/** 🔗️ Owns a bounded unique dependency vector in native identity order. */
function trustedBootstrapDependencies(value: unknown): readonly TrustedBootstrapIdentityV1[] {
  if (!Array.isArray(value) || value.length > 128) throw new Error("trusted dependency vector is not bounded");
  const rows = value.map(trustedBootstrapIdentity);
  if (new Set(rows.map((row) => row.pluginId)).size !== rows.length) throw new Error("trusted dependency identity is duplicated");
  return Object.freeze(rows.sort((left, right) => trustedBootstrapTupleOrder([left.pluginId, left.packageId, left.version], [right.pluginId, right.packageId, right.version])));
}

/** 🧾️ Retains dependency claims from the same bounded descriptor bytes as its protocol. */
function trustedBootstrapDescriptorClaims(bytes: Uint8Array): TrustedBootstrapDescriptorClaimsV1 {
  if (bytes.byteLength === 0 || bytes.byteLength > DOCUMENT_EXECUTION_TARGET_DESCRIPTOR_MAX_BYTES) throw new Error("trusted descriptor dependency bytes are not bounded");
  const decoded = decodePackValue(bytes);
  if (!Buffer.from(encodePackValue(decoded)).equals(Buffer.from(bytes))) throw new Error("trusted descriptor dependency Pack is not canonical or has duplicate fields");
  const descriptor = packValueToExactJson(decoded) as Record<string, unknown>;
  const manifest = descriptor?.manifest as Record<string, unknown>;
  if (!manifest || typeof manifest !== "object" || Array.isArray(manifest)) throw new Error("trusted descriptor manifest is missing");
  // 🔗️ `PluginManifest.dependencies` is `#[value(default, skip_serializing_if = "Vec::is_empty")]`
  // (`🛂️manifest/🦀️.rs:4418`), so a plugin that depends on nothing — `semio-hub-stdio` is exactly
  // that — emits a descriptor with NO `dependencies` key at all. Requiring the key present rejected
  // every dependency-free package, which is the whole trusted bootstrap set. Absent means the empty
  // vector, which is what the encoder's own contract says; the 128 bound still applies to a present one.
  const declaredDependencies = manifest.dependencies === undefined ? [] : manifest.dependencies;
  if (!Array.isArray(declaredDependencies) || declaredDependencies.length > 128) throw new Error("trusted descriptor manifest dependency vector is missing or unbounded");
  const identity = trustedBootstrapIdentity({ pluginId: manifest.pluginId, packageId: descriptor.packageId, version: manifest.version });
  const directDependencies = declaredDependencies.map((value) => {
    const row = documentOpenNeutralObject(value, ["pluginId", "version"]);
    if (typeof row.pluginId !== "string" || row.pluginId.length === 0 || Buffer.byteLength(row.pluginId, "utf8") > 256 || row.pluginId.trim() !== row.pluginId || Buffer.from(row.pluginId, "utf8").toString("utf8") !== row.pluginId || /\p{Cc}/u.test(row.pluginId) || typeof row.version !== "string" || !row.version.startsWith("=")) throw new Error("trusted descriptor dependency is not exact and bounded");
    trustedBootstrapVersion(row.version.slice(1));
    return Object.freeze({ pluginId: row.pluginId, version: row.version });
  });
  if (new Set(directDependencies.map((row) => row.pluginId)).size !== directDependencies.length) throw new Error("trusted descriptor dependency is duplicated");
  return Object.freeze({ identity, executionProtocol: trustedBootstrapExecutionProtocol(descriptor.executionProtocol), directDependencies: Object.freeze(directDependencies) });
}

/** 🧬️ Resolves one package's descriptor-attested dependencies against the selected closure. Every
 * dependency a package's own compiled manifest claims must be IN the closure at the exact compiled
 * version and must be another package; nothing outside it is admitted, and no package's edges are named
 * by this builder. The closure as a whole is held by [`trustedBootstrapResolveClosure`]. */
function trustedBootstrapResolveDependencies(claims: TrustedBootstrapDescriptorClaimsV1, candidates: unknown): readonly TrustedBootstrapIdentityV1[] {
  const selected = trustedBootstrapDependencies(candidates);
  if (selected.length === 0) throw new Error("trusted dependency closure is empty");
  const owner = selected.find((row) => row.pluginId === claims.identity.pluginId);
  if (!owner || owner.packageId !== claims.identity.packageId || owner.version !== claims.identity.version) throw new Error("trusted descriptor dependency owner differs from its selected identity");
  const expected = claims.directDependencies.map((claimed) => {
    if (claimed.pluginId === claims.identity.pluginId) throw new Error(`trusted descriptor dependency ${claimed.pluginId} names its own package`);
    const resolved = selected.find((row) => row.pluginId === claimed.pluginId);
    if (!resolved || claimed.version !== `=${resolved.version}`) throw new Error(`trusted descriptor dependency ${claimed.pluginId} is outside the selected closure or pinned to another version`);
    return resolved;
  });
  return Object.freeze([...expected].sort((left, right) => trustedBootstrapTupleOrder([left.pluginId, left.packageId, left.version], [right.pluginId, right.packageId, right.version])));
}

/** 🔗️ Resolves a whole selected closure the way the hub's `validate_bundle` admits it (`🔏️trusted-catalog/🦀️.rs`): each
 * selected identity is exactly one package's own descriptor identity (a closure row naming another package id is foreign),
 * each package's dependencies resolve by [`trustedBootstrapResolveDependencies`], and the dependency graph is acyclic. The
 * linked profile `local-stdio-gis-open-v1` is also held to its exact edge set — GIS depends on stdio, stdio on nothing — as
 * the hub's profile fence is, so a publication fails where the hub would refuse to load it. Answers every package's
 * resolved dependencies by plugin id. */
function trustedBootstrapResolveClosure(profileId: string, claims: ReadonlyMap<string, TrustedBootstrapDescriptorClaimsV1>, candidates: unknown): ReadonlyMap<string, readonly TrustedBootstrapIdentityV1[]> {
  const selected = trustedBootstrapDependencies(candidates);
  if (claims.size !== selected.length) throw new Error("trusted dependency closure and its package descriptors differ in count");
  const resolved = new Map<string, readonly TrustedBootstrapIdentityV1[]>();
  for (const identity of selected) {
    const own = claims.get(identity.pluginId);
    if (!own || own.identity.pluginId !== identity.pluginId || own.identity.packageId !== identity.packageId || own.identity.version !== identity.version) throw new Error(`trusted dependency closure names ${identity.pluginId} as another package than its own descriptor`);
    resolved.set(identity.pluginId, trustedBootstrapResolveDependencies(own, selected));
  }
  const pending = new Map([...resolved].map(([plugin, dependencies]) => [plugin, dependencies.length]));
  const ready = [...pending].filter(([, count]) => count === 0).map(([plugin]) => plugin);
  let ordered = 0;
  for (let plugin = ready.pop(); plugin !== undefined; plugin = ready.pop()) {
    ordered += 1;
    for (const [dependent, dependencies] of resolved) {
      if (!dependencies.some((dependency) => dependency.pluginId === plugin)) continue;
      const left = pending.get(dependent)! - 1;
      pending.set(dependent, left);
      if (left === 0) ready.push(dependent);
    }
  }
  if (ordered !== resolved.size) throw new Error("trusted dependency closure contains a cycle");
  if (profileId === "local-stdio-gis-open-v1" && (resolved.get("gis")?.map((dependency) => dependency.pluginId).join(",") !== "stdio" || resolved.get("stdio")?.length !== 0))
    throw new Error("local stdio plus GIS profile dependency closure is not exactly gis → stdio");
  return resolved;
}

/** 🛫️ The selection-level rules the final staging and the hub's `validate_bundle` hold a publication to, judged from the package
 * rows and their COMMITTED descriptors alone, so a violation surfaces in seconds instead of after the release builds (ticket
 * 26/09/23 W4: a hosted-only stdio family and a 260-byte profile id each failed only after 15–44 min): the profile id is a
 * bounded `local-…-open-v1` name (`TRUSTED_IDENTITY_MAX_BYTES`); every package identity and declared kind id/schema is a bounded
 * trusted identity; a package without linked codecs declares an artifact kind of its own (its component answers the codec rows)
 * or HOSTS kinds (`manifest.hostedArtifactKinds`, p15) — the hub's own hosted-row rule (`trusted-catalog` descriptor decode): each
 * (id, schema) row once and never also owned, its explicit `owner` another package this one declares as a dependency and this catalog
 * selects BEFORE it (the publisher binds the row to the owner's already-published codec rows; a row the owner publishes no codec for —
 * stdio's definition-only kinds — opens nothing, as in the bootstrap); which kinds its apps OWN is the `describe`
 * gate's `first_owned_codec` law; a linked package's codec registry exists; no artifact kind is owned by editors of two packages (the hub's
 * `artifact_creation_selection` needs one unambiguous editor — c9's GIS probe got 409 when demonstrator re-owned `s.gis.gismap`). Law + fixture: `🌎️hub/🧪️tests/🛫️catalog-selection-preflight`. */
export function trustedBootstrapSelectionFindingsV1(profileId: string, packages: readonly Readonly<{ pluginId: string; componentPackageId: string; outputName: string; linkedCodecRegistry: string | null; linkedCodecRegistryPresent: boolean; descriptor: Record<string, any> }>[]): readonly string[] {
  const bounded = (value: unknown): boolean => typeof value === "string" && value.length > 0 && new TextEncoder().encode(value).length <= 256 && value.trim() === value;
  const findings: string[] = [];
  if (!bounded(profileId) || !/^local-(?:[a-z0-9]+-)+open-v1$/u.test(profileId)) findings.push(`profile id ${JSON.stringify(profileId.slice(0, 96))} is not a bounded local-…-open-v1 name (${new TextEncoder().encode(profileId).length} bytes, bound 256)`);
  const editorOwners = new Map<string, string[]>();
  for (const row of packages) {
    for (const [field, value] of [["pluginId", row.pluginId], ["componentPackageId", row.componentPackageId], ["outputName", row.outputName]] as const) if (!bounded(value)) findings.push(`${row.pluginId}: ${field} is not a bounded trusted identity`);
    const kinds = trustedBootstrapDescriptorKindsV1(row.descriptor);
    const editors = ((row.descriptor.manifest?.apps ?? []) as Record<string, any>[]).filter((app) => app.role === "editor");
    for (const kind of kinds) {
      if (!bounded(kind.id) || !bounded(kind.schema)) findings.push(`${row.pluginId}: artifact kind ${JSON.stringify(String(kind.id).slice(0, 96))} has an unbounded id or schema`);
      if (editors.some((app) => app.io?.artifactSchema === kind.schema || app.dialect?.artifactKind === kind.schema)) editorOwners.set(String(kind.id), [...(editorOwners.get(String(kind.id)) ?? []), row.pluginId]);
    }
    if (row.linkedCodecRegistry !== null) {
      if (!row.linkedCodecRegistryPresent) findings.push(`${row.pluginId}: linked codec registry ${row.linkedCodecRegistry} is missing`);
    }
    const manifest = (row.descriptor.manifest ?? {}) as Record<string, any>;
    const hosted = (manifest.hostedArtifactKinds ?? []) as Record<string, any>[];
    if (row.linkedCodecRegistry === null && kinds.length === 0 && hosted.length === 0) findings.push(`${row.pluginId}: declares no artifact kind, owned or hosted — a trusted-catalog package answers a codec row of its own or hosts kinds of a selected owner`);
    const dependencies = new Set(((manifest.dependencies ?? []) as Record<string, any>[]).map((dependency) => String(dependency.pluginId)));
    const owned = new Set(((manifest.artifactKinds ?? []) as Record<string, any>[]).map((kind) => String(kind.id)));
    const hostedPairs = new Set<string>();
    for (const kind of hosted) {
      const owner = typeof kind.owner === "string" && kind.owner !== "" ? kind.owner : undefined;
      if (!bounded(kind.id) || !bounded(kind.schema)) findings.push(`${row.pluginId}: hosted kind ${JSON.stringify(String(kind.id).slice(0, 96))} has an unbounded id or schema`);
      else if (hostedPairs.has(`${kind.id}\u0000${kind.schema}`) || owned.has(String(kind.id))) findings.push(`${row.pluginId}: hosts ${kind.id} (${kind.schema}) twice or also owns it`);
      else if (!owner || owner === row.pluginId || !dependencies.has(owner) || !packages.slice(0, packages.indexOf(row)).some((candidate) => candidate.pluginId === owner)) findings.push(`${row.pluginId}: hosts ${kind.id}, whose owner ${owner ?? "(none)"} is not another package it declares as a dependency and this catalog selects before it`);
      hostedPairs.add(`${kind.id}\u0000${kind.schema}`);
    }
  }
  for (const [kindId, owners] of editorOwners) if (owners.length > 1) findings.push(`artifact kind ${kindId} is owned by editors of ${owners.join(" and ")} — the hub creates a kind only through one unambiguous editor (host, don't own, another package's kind)`);
  return Object.freeze(findings);
}

/** 🛫️ [[trustedBootstrapSelectionFindingsV1]] over the selected packages' committed owner-root `🔣️.json` descriptors; throws every
 * finding at once. First step of `trusted-catalog-preflight` and `trusted-catalog-bootstrap`. */
export function trustedBootstrapPreflightSelectionV1(repoRoot: string, selection: readonly TrustedBootstrapPackageSpecV1[]): void {
  const registryPath = join(repoRoot, "🧰️framework/🛍️products/💻️os/🔨️modules/🔌️plugin/📇️registry/🤖️generated/🔌️plugins.json");
  if (!existsSync(registryPath)) throw new Error(`trusted catalog preflight needs the generated plugin registry ${relative(repoRoot, registryPath)}; run bun nx run @semio-tech/plugin-registry:generate`);
  const registry = JSON.parse(readFileSync(registryPath, "utf8")) as readonly { pluginId?: unknown; cratePath?: unknown }[];
  const packages = selection.map((spec) => {
    const row = registry.find((entry) => entry.pluginId === spec.pluginId);
    if (typeof row?.cratePath !== "string") throw new Error(`trusted catalog preflight: ${spec.pluginId} is not a row of the generated plugin registry`);
    const descriptor = JSON.parse(readFileSync(join(repoRoot, row.cratePath, "..", "..", "🔣️.json"), "utf8")) as Record<string, any>;
    return { ...spec, linkedCodecRegistryPresent: spec.linkedCodecRegistry !== null && existsSync(join(repoRoot, spec.linkedCodecRegistry)), descriptor };
  });
  const findings = trustedBootstrapSelectionFindingsV1(trustedBootstrapProfileIdV1(selection), packages);
  if (findings.length > 0) throw new Error(`trusted catalog preflight: selection refused before any build:\n${findings.map((finding) => `  - ${finding}`).join("\n")}`);
  console.log(`trusted-catalog-preflight: selection of ${selection.length} packages publishes as ${trustedBootstrapProfileIdV1(selection)} with bounded identities and a codec of its own per package`);
}

/** 🛫️ Fails a publication in seconds, before any build or codec probe: every selected package's COMMITTED owner-root
 * descriptor must pass the same claim rules its fresh build is held to later (canonical bounded Pack, exact `=x.y.z`
 * dependency pins, every dependency inside the selected closure at that package's own version). A stale or malformed
 * declaration therefore surfaces before an hour of fresh release builds, and `describe` is the fix it names. */
export function trustedBootstrapPreflightDescriptorsV1(repoRoot: string, selection: readonly TrustedBootstrapPackageSpecV1[]): void {
  const registryPath = join(repoRoot, "🧰️framework/🛍️products/💻️os/🔨️modules/🔌️plugin/📇️registry/🤖️generated/🔌️plugins.json");
  if (!existsSync(registryPath)) throw new Error(`trusted catalog preflight needs the generated plugin registry ${relative(repoRoot, registryPath)}; run bun nx run @semio-tech/plugin-registry:generate`);
  const registry = JSON.parse(readFileSync(registryPath, "utf8")) as readonly { pluginId?: unknown; cratePath?: unknown }[];
  const claims = selection.map((spec) => {
    const row = registry.find((entry) => entry.pluginId === spec.pluginId);
    if (typeof row?.cratePath !== "string") throw new Error(`trusted catalog preflight: ${spec.pluginId} is not a row of the generated plugin registry`);
    const bytes = trustedBootstrapReadRegular(join(repoRoot, row.cratePath, "..", "..", "🛂️.descriptor.semio"), DOCUMENT_EXECUTION_TARGET_DESCRIPTOR_MAX_BYTES, `committed ${spec.pluginId} descriptor`, () => {});
    try {
      return { spec, claims: trustedBootstrapDescriptorClaims(bytes) };
    } catch (error) {
      throw new Error(`trusted catalog preflight: committed ${spec.pluginId} descriptor refused (${error instanceof Error ? error.message : String(error)}); fix the declaration, then bun nx run @semio-tech/${spec.pluginId}-plugin:describe`);
    } finally {
      bytes.fill(0);
    }
  });
  const closure = claims.map((row) => ({ pluginId: row.spec.pluginId, packageId: row.spec.componentPackageId, version: row.claims.identity.version }));
  try {
    trustedBootstrapResolveClosure(trustedBootstrapProfileIdV1(selection), new Map(claims.map((row) => [row.spec.pluginId, row.claims])), closure);
  } catch (error) {
    throw new Error(`trusted catalog preflight: dependencies refused (${error instanceof Error ? error.message : String(error)})`);
  }
  console.log(`trusted-catalog-preflight: ${claims.length} committed descriptors carry exact, bounded dependencies inside the selected closure`);
}

/** 🛫️ Fails a publication in milliseconds, before the hub build and every release build: each selected package and each extension
 * of one has a `dist/component-dev` deliverable that is exactly the component its committed descriptor names (`hashes.wasmSha256`, the
 * `rebuild-all` invariant), and that component imports only interfaces a closed browser actor admits — the rule the actor build applies
 * to the release component after its build (`browserActorImportAdmissionV1`). Every finding of every component is reported at once,
 * with the fix it needs. */
export function trustedBootstrapPreflightComponentsV1(repoRoot: string, selection: readonly TrustedBootstrapPackageSpecV1[]): void {
  const registryPath = join(repoRoot, "🧰️framework/🛍️products/💻️os/🔨️modules/🔌️plugin/📇️registry/🤖️generated/🔌️plugins.json");
  if (!existsSync(registryPath)) throw new Error(`trusted catalog preflight needs the generated plugin registry ${relative(repoRoot, registryPath)}; run bun nx run @semio-tech/plugin-registry:generate`);
  const registry = JSON.parse(readFileSync(registryPath, "utf8")) as readonly { pluginId?: unknown; cratePath?: unknown; wasmOut?: unknown; role?: unknown; extends?: unknown }[];
  const selected = new Set(selection.map((spec) => spec.pluginId));
  const rows = registry.filter((row) => (row.role === "plugin" && selected.has(String(row.pluginId))) || (row.role === "extension" && selected.has(String(row.extends))));
  const missing = [...selected].filter((pluginId) => !rows.some((row) => row.pluginId === pluginId));
  if (missing.length > 0) throw new Error(`trusted catalog preflight: ${missing.join(", ")} not rows of the generated plugin registry`);
  const findings: string[] = [];
  for (const row of rows) {
    if (typeof row.cratePath !== "string" || typeof row.wasmOut !== "string") { findings.push(`${String(row.pluginId)}: registry row carries no crate path or component name`); continue; }
    const descriptor = trustedBootstrapReadRegular(join(repoRoot, row.cratePath, "..", "..", "🛂️.descriptor.semio"), DOCUMENT_EXECUTION_TARGET_DESCRIPTOR_MAX_BYTES, `committed ${row.pluginId} descriptor`, () => {});
    const named = (packValueToExactJson(decodePackValue(descriptor)) as { hashes?: { wasmSha256?: unknown } }).hashes?.wasmSha256;
    const path = join(repoRoot, row.cratePath, "dist", "component-dev", row.wasmOut);
    if (!existsSync(path)) { findings.push(`${row.pluginId}: no component-dev deliverable ${relative(repoRoot, path)}; run bun nx run @semio-tech/plugin-registry:rebuild-all`); continue; }
    const component = trustedBootstrapReadRegular(path, FRESH_COMPONENT_MAX_BYTES, `${row.pluginId} component-dev deliverable`, () => {});
    try {
      if (createHash("sha256").update(component).digest("hex") !== named) findings.push(`${row.pluginId}: component-dev deliverable is not the component its committed descriptor names; run bun nx run @semio-tech/plugin-registry:rebuild-all`);
      const imports = browserActorImportAdmissionV1(component);
      if (imports.refused.length > 0) findings.push(`${row.pluginId}: imports ${imports.refused.join(", ")}, which no closed browser actor admits; the guest must not link that capability`);
    } catch (error) {
      findings.push(`${row.pluginId}: ${error instanceof Error ? error.message : String(error)}`);
    } finally {
      component.fill(0);
    }
  }
  if (findings.length > 0) throw new Error(`trusted catalog preflight refused ${findings.length} of ${rows.length} components:\n  ${findings.join("\n  ")}`);
  console.log(`trusted-catalog-preflight: ${rows.length} component-dev deliverables (${selected.size} packages + ${rows.length - selected.size} extensions) match their committed descriptors and import only browser-actor-admitted interfaces`);
}

/** 🧮️ Frames all resolved dependency identities in the native generation format. */
function trustedBootstrapDependencyEncoding(value: unknown): Buffer {
  const dependencies = trustedBootstrapDependencies(value);
  return Buffer.concat([trustedBootstrapCount(dependencies.length), ...dependencies.flatMap((row) => [row.pluginId, row.packageId, row.version].map(trustedBootstrapField))]);
}

function trustedBootstrapCodecOrder(left: TrustedBootstrapCodec, right: TrustedBootstrapCodec): number {
  return trustedBootstrapTupleOrder([left.artifactKind, left.artifactSchema, left.packSchemaHash], [right.artifactKind, right.artifactSchema, right.packSchemaHash]);
}

function trustedBootstrapField(value: Uint8Array | string): Buffer {
  const bytes = typeof value === "string" ? Buffer.from(value, "utf8") : Buffer.from(value);
  const length = Buffer.alloc(8);
  length.writeBigUInt64BE(BigInt(bytes.byteLength));
  return Buffer.concat([length, bytes]);
}

function trustedBootstrapCount(value: number): Buffer {
  const bytes = Buffer.alloc(4);
  bytes.writeUInt32BE(value);
  return bytes;
}

/** 🔖️ Retains only the supported protocol attested by a compiled descriptor. */
function trustedBootstrapExecutionProtocol(value: unknown): Readonly<DocumentExecutionProtocolV1> {
  const protocol = documentOpenNeutralObject(value, ["appChannelVersion"]);
  if (protocol.appChannelVersion !== DOCUMENT_EXECUTION_PROTOCOL_APP_CHANNEL_VERSION_V1) throw new Error("trusted generation execution protocol is unsupported");
  return Object.freeze({ appChannelVersion: protocol.appChannelVersion });
}

type TrustedBootstrapBrowserActorV1 = Readonly<{ kind: "none" }> | (DocumentClosedBrowserActorV1 & Readonly<{ path: string; byteLength: number }>);

/** 📦️ Admits private location metadata while preserving the public source-bound identity. */
function trustedBootstrapBrowserActorV1(candidate: unknown, source: DocumentBrowserActorSourceV1, renderer: string): TrustedBootstrapBrowserActorV1 {
  const row = documentOpenNeutralObject(candidate, ["kind"], ["schema", "codegenPolicy", "sha256", "sourceComponentSha256", "sourceDescriptorByteSha256", "policySha256", "importInterfaces", "path", "byteLength"]);
  if (row.kind === "none") return parseDocumentOpenBrowserActorV1(row, source, renderer) as Readonly<{ kind: "none" }>;
  const { path, byteLength, ...identity } = row;
  const plan = parseDocumentOpenBrowserActorV1(identity, source, renderer);
  const lease = documentBrowserActorLeaseFromPlanV1(plan, source, renderer, byteLength);
  if (lease.kind !== "closed-browser-actor" || typeof path !== "string" || Buffer.byteLength(path, "utf8") > 1024 || /[\\:\p{Cc}]/u.test(path) || path.split("/").some((part) => part === "" || part === "." || part === ".."))
    throw new Error("trusted browser actor path or identity is invalid");
  return Object.freeze({ ...lease, path });
}

/** 🧬️ Frames every actor field, including explicit absence, in the immutable generation. */
function trustedBootstrapBrowserActorEncoding(candidate: unknown, source: DocumentBrowserActorSourceV1, renderer: string): Buffer {
  const actor = trustedBootstrapBrowserActorV1(candidate, source, renderer);
  const pieces = [trustedBootstrapField(actor.kind)];
  if (actor.kind === "none") return Buffer.concat(pieces);
  for (const value of [actor.schema, actor.codegenPolicy, actor.path]) pieces.push(trustedBootstrapField(value));
  const length = Buffer.alloc(8);
  length.writeBigUInt64BE(BigInt(actor.byteLength));
  pieces.push(length);
  for (const value of [actor.sha256, actor.sourceComponentSha256, actor.sourceDescriptorByteSha256, actor.policySha256]) pieces.push(trustedBootstrapField(Buffer.from(value, "hex")));
  pieces.push(trustedBootstrapCount(actor.importInterfaces.length));
  for (const value of actor.importInterfaces) pieces.push(trustedBootstrapField(value));
  return Buffer.concat(pieces);
}

/** 📇️ Every selected package's codec rows, keyed by plugin id — open to an N-package closure. */
type TrustedBootstrapCodecSetV1 = Readonly<Record<string, readonly TrustedBootstrapCodec[]>>;

/** 🎯️ One creatable document kind a package's own descriptor declares, in generation order. */
type TrustedBootstrapOpenTargetV1 = Readonly<{
  pluginId: string;
  artifactKind: string;
  artifactSchema: string;
  packSchemaHash: string;
  surfaceId: string;
  appId: string;
  windowKindId: string;
  role: "editor" | "viewer";
  rendererTarget: "wasm";
  parentDialect: Readonly<{ artifactKind: string; standard: string; subset: string }>;
  grant: Readonly<{ read: boolean; write: boolean; observe: boolean }>;
}>;

/** 🖥️ Mirrors `package_actor_renderer` (`🔏️trusted-catalog/🦀️.rs`): a package that opens any document
 * carries a wasm actor, every other selected package a React one. Derived from the package's own
 * target set so a fourth package needs no renderer table. */
function trustedBootstrapPackageRenderer(profile: any, pluginId: string): string {
  return profile.openTargets.some((target: TrustedBootstrapOpenTargetV1) => target.pluginId === pluginId) ? "wasm" : "react";
}

/** 🔢️ Mirrors `trusted_profile_generation`'s open-target ordering byte for byte. */
function trustedBootstrapOpenTargetOrder(left: TrustedBootstrapOpenTargetV1, right: TrustedBootstrapOpenTargetV1, packages: any[]): number {
  const identity = (target: TrustedBootstrapOpenTargetV1): readonly string[] => {
    const owner = packages.find((candidate: any) => candidate.pluginId === target.pluginId);
    if (!owner) throw new Error("trusted bootstrap open target has no selected package");
    return [owner.pluginId, owner.packageId, owner.version, target.artifactKind, target.artifactSchema, target.surfaceId, target.role === "viewer" ? "" : ""];
  };
  return trustedBootstrapTupleOrder(identity(left), identity(right));
}

function trustedBootstrapProfileEncoding(profile: any, codecs: TrustedBootstrapCodecSetV1): Buffer {
  const pieces = [Buffer.from("semio/hub/trusted-profile-generation/v1\0"), trustedBootstrapField(profile.id), trustedBootstrapCount(profile.selectedClosure.length)];
  for (const identity of profile.selectedClosure) {
    const selected = profile.packages.find((candidate: any) => candidate.pluginId === identity.pluginId && candidate.packageId === identity.packageId && candidate.version === identity.version);
    if (!selected) throw new Error("trusted bootstrap package is outside selected closure");
    for (const value of [selected.pluginId, selected.packageId, selected.version, selected.role, selected.componentSha256, selected.componentBlake3, selected.descriptorSha256]) {
      pieces.push(trustedBootstrapField(/^[0-9a-f]{64}$/u.test(value) ? Buffer.from(value, "hex") : value));
    }
    pieces.push(trustedBootstrapField(trustedBootstrapCount(trustedBootstrapExecutionProtocol(selected.executionProtocol).appChannelVersion)));
    pieces.push(
      trustedBootstrapBrowserActorEncoding(selected.browserActor, { componentSha256: selected.componentSha256, descriptorByteSha256: selected.descriptorSha256 }, trustedBootstrapPackageRenderer(profile, selected.pluginId)),
    );
    pieces.push(trustedBootstrapPluginModuleEncoding(trustedBootstrapPluginModuleRecordV1(selected.pluginModule, selected.pluginId)));
    pieces.push(trustedBootstrapDependencyEncoding(selected.dependencies));
    const declared = codecs[selected.pluginId as string];
    if (!declared) throw new Error("trusted bootstrap selected package declares no codec closure");
    const rows = [...declared].sort(trustedBootstrapCodecOrder);
    pieces.push(trustedBootstrapCount(rows.length));
    for (const row of rows) pieces.push(trustedBootstrapField(row.artifactKind), trustedBootstrapField(row.artifactSchema), trustedBootstrapField(Buffer.from(row.packSchemaHash, "hex")));
  }
  // 🎯️ The whole SET behind its own count, in `trusted_profile_generation`'s canonical order (ticket
  // 26/09/18 slice TC3b). A one-target profile frames byte-identically to the retired single-target
  // encoding, so generalising this does not by itself rotate an existing generation id.
  const selectedTargets = [...(profile.openTargets as TrustedBootstrapOpenTargetV1[])].sort((left, right) => trustedBootstrapOpenTargetOrder(left, right, profile.packages));
  pieces.push(trustedBootstrapCount(selectedTargets.length));
  for (const target of selectedTargets) {
    const targetPackage = profile.packages.find((candidate: any) => candidate.pluginId === target.pluginId);
    const targetCodec = (codecs[target.pluginId] ?? []).find((codec) => codec.artifactKind === target.artifactKind && codec.artifactSchema === target.artifactSchema);
    if (!targetPackage || !targetCodec) throw new Error("trusted bootstrap open target has no package codec");
    if (targetCodec.packSchemaHash !== target.packSchemaHash) throw new Error("trusted bootstrap open target pack schema hash differs from its package codec");
    for (const value of [
      targetPackage.pluginId,
      targetPackage.packageId,
      targetPackage.version,
      Buffer.from(targetPackage.componentSha256, "hex"),
      Buffer.from(targetPackage.componentBlake3, "hex"),
      Buffer.from(targetPackage.descriptorSha256, "hex"),
      trustedBootstrapCount(trustedBootstrapExecutionProtocol(targetPackage.executionProtocol).appChannelVersion),
      target.artifactKind,
      target.artifactSchema,
      Buffer.from(targetCodec.packSchemaHash, "hex"),
      target.parentDialect.artifactKind,
      target.parentDialect.standard,
      target.parentDialect.subset,
      target.surfaceId,
      target.appId,
      target.windowKindId,
      target.role,
      target.rendererTarget,
      Buffer.from([Number(target.grant.read), Number(target.grant.write), Number(target.grant.observe)]),
    ])
      pieces.push(trustedBootstrapField(value));
  }
  return Buffer.concat(pieces);
}

function trustedBootstrapClosureEncoding(profile: any): Buffer {
  const pieces = [Buffer.from("semio/hub/trusted-profile-selected-closure/v1\0"), trustedBootstrapCount(profile.selectedClosure.length)];
  for (const identity of profile.selectedClosure) pieces.push(trustedBootstrapField(identity.pluginId), trustedBootstrapField(identity.packageId), trustedBootstrapField(identity.version));
  return Buffer.concat(pieces);
}

function trustedBootstrapPlanGenerationOutcome(issuedGenerationId: string, observedGenerationId: string): "accepted" | "stale" {
  return issuedGenerationId === observedGenerationId ? "accepted" : "stale";
}

