/** 🧾️ Resolves a comma-separated `--packages` list against the selectable closure, in list order. */
/** 📏️ The hub's bound on every trusted identity it holds, a profile id included (`TRUSTED_IDENTITY_MAX_BYTES`,
 * `🌎️hub/🗿️artifact-authority/🔏️trusted-catalog/🦀️.rs`). */
const TRUSTED_PROFILE_ID_MAX_BYTES = 256;

/** 🏷️ The profile name one selection publishes under — a name only: the bundle's profile carries the exact selected closure and its
 * digest. `local-all-open-v1` for the whole selectable closure ([[TRUSTED_BOOTSTRAP_ALL_PACKAGES]]); otherwise the REQUESTED order,
 * `local-<plugin>-…-open-v1` (`--packages stdio,gis` keeps minting `local-stdio-gis-open-v1`), while that fits the hub's identity
 * bound, and `local-<count>-packages-<16 hex of the requested list's sha256>-open-v1` beyond it (ticket 26/09/23 W4: a 34-package
 * list minted a 260-byte name the pointer reader refused after the whole publication). */
export function trustedBootstrapProfileIdV1(selection: readonly TrustedBootstrapPackageSpecV1[]): string {
  const all = TRUSTED_BOOTSTRAP_ALL_PACKAGES.split(",");
  const ids = selection.map((spec) => spec.pluginId);
  if (ids.length === all.length && all.every((pluginId) => ids.includes(pluginId))) return "local-all-open-v1";
  const listed = `local-${ids.join("-")}-open-v1`;
  return Buffer.byteLength(listed, "utf8") <= TRUSTED_PROFILE_ID_MAX_BYTES ? listed : `local-${ids.length}-packages-${createHash("sha256").update(ids.join(",")).digest("hex").slice(0, 16)}-open-v1`;
}

export function trustedBootstrapSelectPackages(list: string): readonly TrustedBootstrapPackageSpecV1[] {
  const requested = (list.trim() === "all" ? TRUSTED_BOOTSTRAP_ALL_PACKAGES : list)
    .split(",")
    .map((part) => part.trim())
    .filter((part) => part.length > 0);
  if (requested.length === 0 || new Set(requested).size !== requested.length) throw new Error("trusted catalog package list is empty or repeats a package");
  return Object.freeze(
    requested.map((pluginId) => {
      const spec = TRUSTED_BOOTSTRAP_PACKAGES.find((candidate) => candidate.pluginId === pluginId);
      if (!spec) throw new Error(`trusted catalog package ${pluginId} is outside the selectable closure (${TRUSTED_BOOTSTRAP_PACKAGES.map((candidate) => candidate.pluginId).join(",")})`);
      return spec;
    }),
  );
}

/** 🧬️ Asks ONE built component for the pack fingerprint of each document kind its OWN compiled
 * descriptor declares, through the `codecs` subcommand of the same descriptor emitter the build
 * already ran. `pairs` are that descriptor's `ArtifactKindSpec { id, schema }` rows: the kind and
 * the schema are the package's own published identities, and only the 32-byte fingerprint — the one
 * thing a manifest cannot state — comes from the component, on the exact bytes about to be
 * published. So a package the hub links no Rust codec for transcribes nothing. */
function trustedBootstrapComponentCodecRowsV1(repoRoot: string, emitter: string, componentPath: string, outPath: string, pairs: readonly (readonly [string, string])[]): Readonly<{ rows: readonly TrustedBootstrapCodec[]; unowned: ReadonlySet<string> }> {
  if (pairs.length === 0) throw new Error("component codec probe requires at least one declared artifact kind");
  const probe = runProbe(emitter, ["codecs", componentPath, "--kinds", pairs.map(([kind, schema]) => `${kind}=${schema}`).join(","), "--out", outPath], { cwd: repoRoot, ...orchestratorBudgetOpts() });
  if (probe.status !== 0) throw new Error(`component codec probe failed (${probe.status}): ${probe.stderr.trim() || probe.stdout.trim()}`);
  const document = JSON.parse(readFileSync(outPath, "utf8"));
  if (document?.schema !== "semio.plugin.component-codec-rows/v1" || !Array.isArray(document.rows) || !Array.isArray(document.unowned) || document.rows.length + document.unowned.length !== pairs.length) throw new Error("component codec probe answered outside its exact declared closure");
  const unowned = new Set<string>(document.unowned.map((value: unknown) => {
    const row = documentOpenNeutralObject(value, ["artifactKind", "artifactSchema"]);
    if (!pairs.some(([kind, schema]) => kind === row.artifactKind && schema === row.artifactSchema)) throw new Error("component codec probe reported an unowned kind the descriptor does not declare");
    return String(row.artifactKind);
  }));
  const rows = document.rows.map((value: unknown) => {
    const row = documentOpenNeutralObject(value, ["artifactKind", "artifactSchema", "packSchemaHash"]);
    if (!pairs.some(([kind, schema]) => kind === row.artifactKind && schema === row.artifactSchema) || !/^(?!0{64}$)[0-9a-f]{64}$/u.test(String(row.packSchemaHash)))
      throw new Error("component codec row is not a bounded nonzero identity the descriptor declares");
    return Object.freeze({ artifactKind: row.artifactKind as string, artifactSchema: row.artifactSchema as string, packSchemaHash: row.packSchemaHash as string });
  });
  if (new Set(rows.map((row: TrustedBootstrapCodec) => row.artifactKind)).size !== rows.length || rows.some((row: TrustedBootstrapCodec) => unowned.has(row.artifactKind))) throw new Error("component codec probe repeated an artifact kind");
  return Object.freeze({ rows: Object.freeze(rows.sort(trustedBootstrapCodecOrder)), unowned });
}

/** ⛓️ The declared kinds a LINKED package does not own. The hub executes a linked package's documents only through
 * the native codecs it links (`linkedCodecRegistry`), and every document-open target must bind one of them
 * (`validate_bundle`: "trusted document-open target is bound to no native codec of its own package"), so a kind the
 * descriptor declares without a linked row (an editor declaring a kind its package links no codec for) is unowned:
 * declared, never a hub open target; Stdio and GIS link a codec for every kind they declare. A declared kind whose linked row carries another
 * schema is an identity conflict, not an unowned kind. Law + fixture: `🌎️hub/🧪️tests/⛓️linked-codec-ownership`. */
export function trustedBootstrapLinkedUnownedKindsV1(pairs: readonly (readonly [string, string])[], linked: readonly TrustedBootstrapCodec[]): ReadonlySet<string> {
  const unowned = new Set<string>();
  for (const [kind, schema] of pairs) {
    const row = linked.find((codec) => codec.artifactKind === kind);
    if (!row) unowned.add(kind);
    else if (row.artifactSchema !== schema) throw new Error(`linked codec ${kind} carries schema ${row.artifactSchema}, its descriptor declares ${schema}`);
  }
  return Object.freeze(unowned);
}

/** 🗂️ Every `ArtifactKindSpec` one verified descriptor declares, deduplicated by kind id and in
 * declaration order. This is `validate_descriptor_open_target`'s own discoverability union: a spec
 * declared at PLUGIN level (`PluginBuilder::artifact_kind`, the channel GIS and Stdio still use) or
 * on the OWNING APP, which is where a package migrated onto the declaration tree stitches it. */
/** 🏠️ The kinds one package HOSTS (`manifest.hostedArtifactKinds`: `PluginBuilder::host_artifact` and embedded surfaces of
 * another plugin's artifact): each row's explicit `owner` must be a declared dependency already published in this catalog —
 * never read off the kind id (an embedded editor's `3d.cad` names no plugin); a hosted row binds the
 * owner's verified codec row (codec rows never move), and a row the owner publishes no codec for opens nothing — the owner's
 * own rule for its unlinked kinds (the owner publishes ONE codec row per kind, so a kind's other document schemas stay
 * unbound). */
function trustedBootstrapHostedKindsV1(pluginId: string, descriptor: Record<string, any>, codecs: Readonly<Record<string, readonly TrustedBootstrapCodec[]>>): Readonly<{ pairs: readonly (readonly [string, string])[]; rows: readonly TrustedBootstrapCodec[]; unowned: ReadonlySet<string>; unbound: ReadonlySet<string> }> {
  const manifest = descriptor.manifest as Record<string, any>;
  const dependencies = new Set(((manifest.dependencies ?? []) as Record<string, any>[]).map((dependency) => String(dependency.pluginId)));
  const hosted = (manifest.hostedArtifactKinds ?? []) as Record<string, any>[];
  const pairs = hosted.map((kind) => [String(kind.id), String(kind.schema)] as const);
  const rows: TrustedBootstrapCodec[] = [];
  const unowned = new Set<string>();
  const unbound = new Set<string>();
  for (const kind of hosted) {
    const [id, schema] = [String(kind.id), String(kind.schema)];
    const owner = typeof kind.owner === "string" ? kind.owner : "";
    if (!owner || owner === pluginId || !dependencies.has(owner)) throw new Error(`trusted catalog package ${pluginId} hosts ${id}, whose owner ${JSON.stringify(owner)} is not one of its declared dependencies`);
    const published = codecs[owner];
    if (!published) throw new Error(`trusted catalog package ${pluginId} hosts ${id}, whose owner ${owner} is not published before it in this catalog`);
    const row = published.find((codec) => codec.artifactKind === id && codec.artifactSchema === schema);
    if (row) rows.push(row);
    else {
      unowned.add(id);
      unbound.add(`${id} ${schema}`);
    }
  }
  for (const row of rows) unowned.delete(row.artifactKind);
  return Object.freeze({ pairs: Object.freeze(pairs), rows: Object.freeze(rows), unowned, unbound });
}

function trustedBootstrapDescriptorKindsV1(descriptor: Record<string, any>): readonly Record<string, any>[] {
  const manifest = descriptor.manifest as Record<string, any>;
  const apps = (manifest.apps ?? []) as Record<string, any>[];
  const declared = [...((manifest.artifactKinds ?? []) as Record<string, any>[]), ...apps.flatMap((app) => (app.artifactKinds ?? []) as Record<string, any>[])];
  const seen = new Set<string>();
  return Object.freeze(declared.filter((kind) => !seen.has(String(kind.id)) && seen.add(String(kind.id))));
}

/** 🎯️ The document-open targets one package's exact compiled descriptor declares, answered by the hub
 * binary that validates this generation (`os-hub trusted-catalog open-targets`, the Rust pairing rule
 * `descriptor_open_targets` in `🔏️trusted-catalog/🦀️.rs` that `validate_descriptor_open_target` also
 * applies), each bound to the package's own verified codec row. The rule has one implementation; this is
 * its caller. */
function trustedBootstrapHubOpenTargetsV1(hubBinary: string, pluginId: string, descriptor: Uint8Array, codecs: readonly TrustedBootstrapCodec[], unowned: ReadonlySet<string>, unbound: ReadonlySet<string> = new Set()): readonly TrustedBootstrapOpenTargetV1[] {
  const answer = spawnSync(hubBinary, ["trusted-catalog", "open-targets"], { input: descriptor, maxBuffer: 4 * 1024 * 1024, timeout: 120_000, killSignal: "SIGKILL", env: { PATH: process.env.PATH ?? "" } });
  if (answer.error || answer.status !== 0) throw new Error(`hub open-target answer for ${pluginId} failed (${answer.status ?? answer.signal ?? answer.error?.message}): ${String(answer.stderr ?? "").trim().slice(0, 512)}`);
  const document = documentOpenNeutralObject(JSON.parse(String(answer.stdout)), ["schema", "targets"]);
  if (document.schema !== "semio.hub.trusted-catalog-descriptor-open-targets/v1" || !Array.isArray(document.targets)) throw new Error(`hub open-target answer for ${pluginId} is outside its schema`);
  return Object.freeze(
    document.targets.filter((value: any) => !unowned.has(String(value?.artifactKind)) && !unbound.has(`${String(value?.artifactKind)} ${String(value?.artifactSchema)}`)).map((value: unknown) => {
      const row = documentOpenNeutralObject(value, ["artifactKind", "artifactSchema", "surfaceId", "appId", "windowKindId", "role", "rendererTarget", "parentDialect", "grant"]);
      const codec = codecs.find((candidate) => candidate.artifactKind === row.artifactKind && candidate.artifactSchema === row.artifactSchema);
      if (!codec) throw new Error(`trusted bootstrap open target ${row.artifactKind} has no verified codec row`);
      const dialect = documentOpenNeutralObject(row.parentDialect, ["artifactKind", "standard", "subset"]);
      const grant = documentOpenNeutralObject(row.grant, ["read", "write", "observe"]);
      return Object.freeze({
        pluginId,
        artifactKind: String(row.artifactKind),
        artifactSchema: String(row.artifactSchema),
        packSchemaHash: codec.packSchemaHash,
        surfaceId: String(row.surfaceId),
        appId: String(row.appId),
        windowKindId: String(row.windowKindId),
        role: row.role === "viewer" ? ("viewer" as const) : ("editor" as const),
        rendererTarget: "wasm" as const,
        parentDialect: Object.freeze({ artifactKind: String(dialect.artifactKind), standard: String(dialect.standard), subset: String(dialect.subset) }),
        grant: Object.freeze({ read: grant.read === true, write: grant.write === true, observe: grant.observe === true }),
      });
    }),
  );
}

/** 🏗️ Produces one immutable closed N-package generation without loading or registering codecs. */

/** 🎯 The published root named by `OS_HUB_TRUSTED_CATALOG_SOURCE`, or none. A bind is never
 * discovered: an auto-selected root republishes whatever guest bytes it happened to hold, which is
 * how a rebuilt guest silently failed to reach a fresh catalog. The named root is verified against
 * its own content hashes by {@link bindTrustedCatalogFromPublished}; without one, every package is
 * built fresh from source. */
function resolveTrustedCatalogBindSource(): string | undefined {
  const explicit = process.env.OS_HUB_TRUSTED_CATALOG_SOURCE;
  if (!explicit) return undefined;
  const root = resolve(explicit);
  const trusted = existsSync(join(root, "current.json")) ? root : join(root, "trusted-catalog");
  if (!existsSync(join(trusted, "current.json"))) throw new Error(`OS_HUB_TRUSTED_CATALOG_SOURCE has no current pointer: ${explicit}`);
  return trusted;
}

/** 📥 Bind a published generation into `dataRoot` by content-hash verify + copy — never rebuilds wasm. */
function bindTrustedCatalogFromPublished(dataRoot: string, sourceTrustedRoot: string, selection: readonly TrustedBootstrapPackageSpecV1[]): TrustedBootstrapMaterializationV1 {
  const sourceDataRoot = dirname(sourceTrustedRoot);
  const published = trustedBootstrapCurrent(sourceDataRoot);
  if (!published) throw new Error(`published catalog source is not loadable: ${sourceTrustedRoot}`);
  const wanted = selection.map((spec) => spec.pluginId);
  const bundleMeta = JSON.parse(readFileSync(published.bundlePath, "utf8")) as { packages?: { pluginId: string }[] };
  const have = new Set((bundleMeta.packages ?? []).map((row) => row.pluginId));
  for (const pluginId of wanted) if (!have.has(pluginId)) throw new Error(`published catalog missing package ${pluginId}`);
  trustedBootstrapVerifyPublication(sourceDataRoot, { profileId: published.profileId, generationId: published.generationId, bundleSha256: published.bundleSha256, bundlePath: published.bundlePath });
  const trustedRoot = join(dataRoot, "trusted-catalog");
  mkdirSync(trustedRoot, { recursive: true, mode: 0o700 });
  if (process.platform !== "win32") chmodSync(trustedRoot, 0o700);
  const generations = join(trustedRoot, "generations");
  mkdirSync(generations, { recursive: true, mode: 0o700 });
  const generationRoot = join(generations, published.generationId);
  const sourceGeneration = join(sourceTrustedRoot, "generations", published.generationId);
  if (!existsSync(sourceGeneration)) throw new Error(`published generation directory missing: ${sourceGeneration}`);
  if (!existsSync(generationRoot)) {
    cpSync(sourceGeneration, generationRoot, { recursive: true });
    trustedBootstrapFsyncDirectory(generations);
  }
  const bundlePath = join(generationRoot, "trusted-catalog.json");
  const bundleBytes = trustedBootstrapReadRegular(bundlePath, 4 * 1024 * 1024, "bound catalog bundle", () => {});
  try {
    if (createHash("sha256").update(bundleBytes).digest("hex") !== published.bundleSha256) throw new Error("copied catalog bundle hash mismatch");
    const selected = JSON.parse(new TextDecoder().decode(bundleBytes)) as { packages: any[] };
    trustedBootstrapVerifyGeneration(generationRoot, bundleBytes, new Map(selected.packages.map((record) => [record.pluginId, trustedBootstrapGenerationReceipt(record)])), () => {});
  } finally {
    bundleBytes.fill(0);
  }
  const pointer = Buffer.from(`${JSON.stringify({
    profileId: published.profileId,
    generationId: published.generationId,
    bundleSha256: published.bundleSha256,
    publicationRevision: published.publicationRevision,
  })}\n`, "utf8");
  if (!existsSync(join(trustedRoot, "current.json"))) {
    trustedBootstrapWriteNew(join(trustedRoot, "current.json"), pointer, () => {});
    trustedBootstrapFsyncDirectory(trustedRoot);
  }
  return Object.freeze({ profileId: published.profileId, generationId: published.generationId, bundleSha256: published.bundleSha256, bundlePath });
}

export async function materializeTrustedCatalogBundle(repoRoot: string, dataRoot: string, selection: readonly TrustedBootstrapPackageSpecV1[], hubBinary: string): Promise<TrustedBootstrapMaterializationV1> {
  const bindSource = resolveTrustedCatalogBindSource();
  if (bindSource) {
    const bound = bindTrustedCatalogFromPublished(dataRoot, bindSource, selection);
    console.log(`trusted-catalog-bind: source=${bindSource} generation=${bound.generationId} packages=${selection.map((spec) => spec.pluginId).join(",")} wasm=skipped`);
    return bound;
  }
  trustedBootstrapPreflightDescriptorsV1(repoRoot, selection);
  const trustedRoot = join(dataRoot, "trusted-catalog");
  mkdirSync(trustedRoot, { recursive: true, mode: 0o700 });
  if (lstatSync(trustedRoot).isSymbolicLink() || !lstatSync(trustedRoot).isDirectory()) throw new Error("trusted catalog root must be a regular private directory");
  if (process.platform !== "win32") chmodSync(trustedRoot, 0o700);
  const nonce = randomBytes(16).toString("hex");
  const buildRoot = join(trustedRoot, `build-${nonce}`);
  const stageRoot = join(trustedRoot, `staging-${nonce}`);
  mkdirSync(buildRoot, { mode: 0o700 });
  mkdirSync(stageRoot, { mode: 0o700 });
  const buildControl = trustedBootstrapBuildControl(buildBudgetMs());
  const { control } = buildControl;
  const checkBuild = () => {
    if (control.cancelled() || control.remainingMs() <= 0) throw new Error("trusted catalog build cancelled");
  };
  try {
    const { codecs: linkedCodecs, gisVersion } = captureTrustedBootstrapCodecsV1(repoRoot, () => {
      if (control.cancelled() || control.remainingMs() <= 0) throw new Error("trusted codec capture cancelled");
      control.checkpoint("capture-codecs", 0, 8);
    });
    const requests = selection.map((spec) => ({ pluginId: spec.pluginId, cargoPackage: spec.cargoPackage, componentPackageId: spec.componentPackageId, outputName: spec.outputName, componentProfile: "wasm-release" as const, rootCdylib: true }));
    const receipts = new Map<string, FreshComponentReceiptV1>();
    const descriptorClaims = new Map<string, TrustedBootstrapDescriptorClaimsV1>();
    const browserActors = new Map<string, TrustedBootstrapBrowserActorV1>();
    const pluginModules = new Map<string, TrustedBootstrapPluginModuleRecordV1>();
    const descriptorJson = new Map<string, Record<string, any>>();
    const codecs: Record<string, readonly TrustedBootstrapCodec[]> = {};
    const openTargets: TrustedBootstrapOpenTargetV1[] = [];
    const declaredOpenTargets = new Map<string, (codecs: readonly TrustedBootstrapCodec[], unowned: ReadonlySet<string>, unbound: ReadonlySet<string>) => readonly TrustedBootstrapOpenTargetV1[]>();
    const unownedKinds = new Map<string, ReadonlySet<string>>();
    for (const request of requests) {
      const spec = selection.find((candidate) => candidate.pluginId === request.pluginId)!;
      const target = join(buildRoot, `${request.pluginId}-target`);
      const stage = join(stageRoot, "packages", request.pluginId);
      mkdirSync(target, { recursive: true, mode: 0o700 });
      mkdirSync(stage, { recursive: true, mode: 0o700 });
      let derivedActor: ClosedBrowserActorArtifactV1 | undefined;
      try {
        const { receipt, derived: componentSha256 } = await produceFreshComponentV1(repoRoot, request, target, stage, control, (lease) =>
          lease.consume(async (component) => createHash("sha256").update(component).digest("hex")),
        );
        if (componentSha256 !== receipt.component.sha256 || (derivedActor && derivedActor.componentSha256 !== componentSha256)) throw new Error(`fresh ${request.pluginId} derivation differs from its verified component`);
        if (receipt.pluginId !== request.pluginId || receipt.packageId !== request.componentPackageId) throw new Error(`fresh ${request.pluginId} receipt identity changed after production`);
        const descriptor = trustedBootstrapReadRegular(join(stage, "descriptor.semio"), DOCUMENT_EXECUTION_TARGET_DESCRIPTOR_MAX_BYTES, "fresh compiled descriptor protocol", checkBuild);
        try {
          if (descriptor.byteLength !== receipt.descriptor.byteLength || createHash("sha256").update(descriptor).digest("hex") !== receipt.descriptor.sha256) throw new Error("fresh descriptor protocol bytes differ from the producer receipt");
          descriptorClaims.set(request.pluginId, trustedBootstrapDescriptorClaims(descriptor));
          descriptorJson.set(request.pluginId, packValueToExactJson(decodePackValue(descriptor)) as Record<string, any>);
          const descriptorCopy = Uint8Array.from(descriptor);
          declaredOpenTargets.set(request.pluginId, (rows, unowned, unbound) => {
            try {
              return trustedBootstrapHubOpenTargetsV1(hubBinary, request.pluginId, descriptorCopy, rows, unowned, unbound);
            } finally {
              descriptorCopy.fill(0);
            }
          });
        } finally {
          descriptor.fill(0);
        }
        // 🧬️ The package's codec closure. A package the hub LINKS Rust codecs for must carry exactly
        // the rows its compiled provider previews, so those come from the same registry the provider
        // is generated from; every other package answers for itself, through the `codecs` subcommand
        // of the descriptor emitter this build already produced, on these exact component bytes.
        const manifestKinds = trustedBootstrapDescriptorKindsV1(descriptorJson.get(request.pluginId)!).map((kind) => [String(kind.id), String(kind.schema)] as const);
        const hostedKinds = trustedBootstrapHostedKindsV1(request.pluginId, descriptorJson.get(request.pluginId)!, codecs);
        if (spec.linkedCodecRegistry) {
          const linked = linkedCodecs[request.pluginId as "gis" | "stdio"];
          if (!linked || linked.length === 0) throw new Error(`trusted codec capture carries no linked closure for ${request.pluginId}`);
          codecs[request.pluginId] = linked;
          unownedKinds.set(request.pluginId, trustedBootstrapLinkedUnownedKindsV1(manifestKinds, linked));
        } else if (manifestKinds.length === 0 && hostedKinds.pairs.length > 0) {
          codecs[request.pluginId] = [];
          unownedKinds.set(request.pluginId, hostedKinds.unowned);
        } else {
          const emitter = join(target, "debug", process.platform === "win32" ? "semio-framework-plugin-describe.exe" : "semio-framework-plugin-describe");
          const answered = trustedBootstrapComponentCodecRowsV1(repoRoot, emitter, join(stage, "component.wasm"), join(target, "component-codecs.json"), manifestKinds);
          codecs[request.pluginId] = answered.rows;
          unownedKinds.set(request.pluginId, answered.unowned);
        }
        for (const declared of declaredOpenTargets.get(request.pluginId)!([...codecs[request.pluginId]!, ...hostedKinds.rows], unownedKinds.get(request.pluginId) ?? new Set(), hostedKinds.unbound)) openTargets.push(declared);
        const pluginOpensDocuments = openTargets.some((declared) => declared.pluginId === request.pluginId);
        if (pluginOpensDocuments) {
          const componentBytes = trustedBootstrapReadRegular(join(stage, "component.wasm"), DOCUMENT_EXECUTION_TARGET_COMPONENT_MAX_BYTES, `fresh ${request.pluginId} component for closed actor`, checkBuild);
          try {
            derivedActor = await buildClosedBrowserActorArtifactV1(componentBytes, { cancelled: () => control.cancelled() || control.remainingMs() <= 0, progress: (phase, completed, total) => control.checkpoint(`actor-${phase}`, completed, total) });
          } finally {
            componentBytes.fill(0);
          }
          if (derivedActor.componentSha256 !== componentSha256) throw new Error(`fresh ${request.pluginId} closed actor source differs from its verified component`);
        }
        const actor = trustedBootstrapBrowserActorV1(
          derivedActor
            ? {
                kind: "closed-browser-actor",
                schema: derivedActor.schema,
                codegenPolicy: derivedActor.codegenPolicy,
                sha256: derivedActor.sha256,
                sourceComponentSha256: componentSha256,
                sourceDescriptorByteSha256: receipt.descriptor.sha256,
                policySha256: derivedActor.policySha256,
                importInterfaces: derivedActor.importInterfaces,
                byteLength: derivedActor.byteLength,
                path: `packages/${request.pluginId}/browser/closed-actor.mjs`,
              }
            : { kind: "none" },
          { componentSha256, descriptorByteSha256: receipt.descriptor.sha256 },
          pluginOpensDocuments ? "wasm" : "react",
        );
        if (derivedActor) {
          mkdirSync(join(stage, "browser"), { mode: 0o700 });
          trustedBootstrapWriteNew(join(stage, "browser", "closed-actor.mjs"), derivedActor.bytes, checkBuild);
          trustedBootstrapFsyncDirectory(join(stage, "browser"));
        }
        browserActors.set(request.pluginId, actor);
        pluginModules.set(request.pluginId, await trustedBootstrapPluginModuleV1(repoRoot, request, stage, stageRoot, target, receipt, control, checkBuild));
        receipts.set(request.pluginId, receipt);
      } finally {
        derivedActor?.bytes.fill(0);
      }
    }
    const gis = receipts.get("gis");
    if (gis && gis.version !== gisVersion) throw new Error("fresh GIS component version differs from captured native codecs");
    for (const spec of selection) {
      const rows = codecs[spec.pluginId] ?? [];
      if (rows.length === 0) throw new Error(`trusted ${spec.pluginId} closure carries no artifact codec`);
      // Openability is derived from verified descriptor editor targets (TC5); the table bit is advisory.
    }
    // 🔢️ `validate_bundle` requires the selected closure in canonical identity order, which is the
    // same order `trusted_profile_generation` frames it in; the REQUESTED order only names the
    // profile, so `--packages stdio,gis` keeps minting `local-stdio-gis-open-v1`.
    const selectedClosure = selection
      .map((spec) => ({ pluginId: spec.pluginId, packageId: spec.componentPackageId, version: receipts.get(spec.pluginId)!.version }))
      .sort((left, right) => trustedBootstrapTupleOrder([left.pluginId, left.packageId, left.version], [right.pluginId, right.packageId, right.version]));
    const dependencies = trustedBootstrapResolveClosure(trustedBootstrapProfileIdV1(selection), descriptorClaims, selectedClosure);
    const packageSummary = selectedClosure.map((identity) => {
      const receipt = receipts.get(identity.pluginId)!;
      return {
        pluginId: identity.pluginId,
        packageId: identity.packageId,
        version: identity.version,
        role: "plugin",
        componentSha256: receipt.component.sha256,
        componentBlake3: receipt.component.blake3,
        descriptorSha256: receipt.descriptor.sha256,
        dependencies: dependencies.get(identity.pluginId)!,
        executionProtocol: descriptorClaims.get(identity.pluginId)!.executionProtocol,
        browserActor: browserActors.get(identity.pluginId)!,
        pluginModule: pluginModules.get(identity.pluginId)!,
        codecCount: codecs[identity.pluginId]!.length,
        targetCount: openTargets.filter((declared) => declared.pluginId === identity.pluginId).length,
      };
    });
    const profileSummary = { id: trustedBootstrapProfileIdV1(selection), selectedClosure, packages: packageSummary, openTargets };
    const selectedClosureSha256 = createHash("sha256").update(trustedBootstrapClosureEncoding(profileSummary)).digest("hex");
    const generationId = createHash("sha256").update(trustedBootstrapProfileEncoding(profileSummary, codecs)).digest("hex");
    const file = (plugin: string, receipt: FreshComponentReceiptV1) => ({
      pluginId: plugin,
      packageId: receipt.packageId,
      version: receipt.version,
      role: "plugin",
      dependencies: dependencies.get(plugin)!,
      component: { path: `packages/${plugin}/component.wasm`, byteLength: receipt.component.byteLength, sha256: receipt.component.sha256, blake3: receipt.component.blake3 },
      descriptor: { path: `packages/${plugin}/descriptor.semio`, byteLength: receipt.descriptor.byteLength, sha256: receipt.descriptor.sha256 },
      executionProtocol: descriptorClaims.get(plugin)!.executionProtocol,
      browserActor: browserActors.get(plugin)!,
      pluginModule: pluginModules.get(plugin)!,
      nativeCodecs: codecs[plugin],
      openTargets: openTargets.filter((declared) => declared.pluginId === plugin).map(({ pluginId: _owner, ...target }) => target),
    });
    const bundle = {
      schemaVersion: 3,
      profiles: [
        {
          id: profileSummary.id,
          selectedClosure,
          selectedClosureSha256,
          openTargets: openTargets.map(({ pluginId: owner, ...target }) => ({ package: selectedClosure.find((identity) => identity.pluginId === owner)!, target })),
          generationId,
        },
      ],
      packages: selectedClosure.map((identity) => file(identity.pluginId, receipts.get(identity.pluginId)!)),
    };
    const bundleBytes = Buffer.from(`${JSON.stringify(bundle)}\n`, "utf8");
    if (bundleBytes.byteLength > 4 * 1024 * 1024) throw new Error("trusted catalog bundle exceeds 4 MiB");
    const bundlePath = join(stageRoot, "trusted-catalog.json");
    trustedBootstrapWriteNew(bundlePath, bundleBytes, checkBuild);
    for (const identity of selectedClosure) trustedBootstrapFsyncDirectory(join(stageRoot, "packages", identity.pluginId));
    trustedBootstrapFsyncDirectory(join(stageRoot, "packages"));
    trustedBootstrapFsyncDirectory(join(stageRoot, "plugin-modules"));
    trustedBootstrapFsyncDirectory(stageRoot);
    if (control.cancelled() || control.remainingMs() <= 0) throw new Error("trusted catalog bootstrap cancelled before publication");
    const generations = join(trustedRoot, "generations");
    mkdirSync(generations, { recursive: true, mode: 0o700 });
    if (lstatSync(generations).isSymbolicLink() || !lstatSync(generations).isDirectory()) throw new Error("trusted generations root must be a regular directory");
    const generationRoot = join(generations, generationId);
    const checkGeneration = () => {
      if (control.cancelled() || control.remainingMs() <= 0) throw new Error("trusted catalog generation cancelled before publication");
      control.checkpoint("verify-generation", 8, 8);
    };
    if (existsSync(generationRoot)) {
      trustedBootstrapVerifyGeneration(
        generationRoot,
        bundleBytes,
        new Map(bundle.packages.map((record) => [record.pluginId, trustedBootstrapGenerationReceipt(record)])),
        checkGeneration,
      );
      rmSync(stageRoot, { recursive: true, force: true });
    } else {
      trustedBootstrapVerifyGeneration(stageRoot, bundleBytes, new Map(bundle.packages.map((record) => [record.pluginId, trustedBootstrapGenerationReceipt(record)])), checkGeneration);
      renameSync(stageRoot, generationRoot);
      trustedBootstrapFsyncDirectory(generations);
    }
    const bundleSha256 = createHash("sha256").update(bundleBytes).digest("hex");
    return { profileId: profileSummary.id, generationId, bundleSha256, bundlePath: join(generationRoot, "trusted-catalog.json") };
  } catch (error) {
    rmSync(stageRoot, { recursive: true, force: true });
    throw error;
  } finally {
    buildControl.close();
    rmSync(buildRoot, { recursive: true, force: true });
  }
}

function trustedBootstrapReadRegular(path: string, maximum: number, label: string, check: () => void): Uint8Array {
  const bytes = readStableBuildFile(path, maximum, { remaining: maximum }, check);
  if (bytes.byteLength === 0) throw new Error(`${label} is empty`);
  return bytes;
}

/** 🧿️ Rebinds captured rotation bytes to the already retained current receipt before decoding. */
function trustedBootstrapReadCurrentBundle(current: TrustedBootstrapMaterializationV1, check: () => void): Record<string, any> {
  const bytes = trustedBootstrapReadRegular(current.bundlePath, 4 * 1024 * 1024, "trusted rotation source bundle", check);
  try {
    if (createHash("sha256").update(bytes).digest("hex") !== current.bundleSha256) throw new Error("trusted rotation source bundle differs from its retained digest");
    const bundle = JSON.parse(new TextDecoder("utf-8", { fatal: true }).decode(bytes));
    if (bundle.schemaVersion !== 3 || bundle.profiles?.length !== 1 || !Array.isArray(bundle.packages) || bundle.packages.length === 0 || bundle.profiles[0]?.id !== current.profileId || bundle.profiles[0]?.generationId !== current.generationId)
      throw new Error("trusted rotation source differs from the exact retained profile generation");
    return bundle;
  } finally {
    bytes.fill(0);
  }
}

/** 🌉️ Executes the cold-map laws against the exact verified GIS bytes retained by one generation. */
async function proveTrustedGisColdMapComponentV1(repoRoot: string, current: TrustedBootstrapMaterializationV1, cargoTargetDir: string): Promise<void> {
