        { pluginId: "requester", instanceId: fixture.instanceId },
        { req: BigInt(fixture.requestId), extensionId: fixture.extensionId, capability: fixture.capability, requestJson: JSON.stringify(fixture.request) },
        async () => {
          throw refusal;
