          expect(`${name}@${aspect} x=${ndcX.toFixed(3)}`).toBe(`${name}@${aspect} x=${Math.max(Math.min(ndcX, 0.999), -0.999).toFixed(3)}`);
          expect(`${name}@${aspect} y=${ndcY.toFixed(3)}`).toBe(`${name}@${aspect} y=${Math.max(Math.min(ndcY, 0.999), -0.999).toFixed(3)}`);
